import crypto from 'node:crypto'

export interface ConnectorConfig {
  intercomWebhookSecret: string
  zendeskApiToken: string
  zendeskSubdomain: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  topic: string
  data: {
    item: {
      type: string
      id: string
      url: string
    }
  }
}

export interface ZendeskTicketResponse {
  ticket: {
    id: number
    subject: string
    description: string
    status: string
  }
}

export interface HandleResult {
  ticketId: number
  subject: string
  status: string
}

function verifySignature(secret: string, body: string, signature: string): boolean {
  const expected = crypto.createHmac('sha1', secret).update(body).digest('hex')
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.data?.item) {
    throw new Error('Missing required field: data.item')
  }
  if (payload.data.item.type !== 'conversation') {
    throw new Error(`Expected conversation item, got ${payload.data.item.type}`)
  }
  if (!payload.data.item.id) {
    throw new Error('Missing required field: data.item.id')
  }
  if (!payload.data.item.url) {
    throw new Error('Missing required field: data.item.url')
  }

  const conversationId = payload.data.item.id
  const conversationUrl = payload.data.item.url

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const requestBody = {
    ticket: {
      subject: conversationUrl,
      comment: {
        body: `Intercom conversation ID: ${conversationId}`
      }
    }
  }

  const response = await fetchImpl(zendeskUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.zendeskApiToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} from ${zendeskUrl}`)
  }

  const result = await response.json() as ZendeskTicketResponse
  return {
    ticketId: result.ticket.id,
    subject: result.ticket.subject,
    status: result.ticket.status
  }
}

export function verifyIntercomWebhook(
  secret: string,
  rawBody: string,
  signatureHeader: string | null
): void {
  if (!signatureHeader) {
    throw new Error('Missing X-Hub-Signature header')
  }
  if (!verifySignature(secret, rawBody, signatureHeader)) {
    throw new Error('Invalid Intercom webhook signature')
  }
}

