        ticket: {
          subject: 'https://app.intercom.com/a/apps/123/inbox/conversations/456',
          comment: { body: 'Intercom conversation ID: 456' }
        }
      })
      return jsonResponse({
        ticket: { id: 789, subject: 'https://app.intercom.com/a/apps/123/inbox/conversations/456', description: 'Intercom conversation ID: 456', status: 'new' }
      }, 201)
    })

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '456',
          url: 'https://app.intercom.com/a/apps/123/inbox/conversations/456'
        }
      }
    }

    const config: ConnectorConfig = {
      intercomWebhookSecret: 'secret',
      zendeskApiToken: 'test-token',
      zendeskSubdomain: 'example',
      fetch
    }

    const result = await handle(payload, config)
    expect(result.ticketId).toBe(789)
    expect(calls.length).toBe(1)
  })

  it('throws when data.item is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { type: 'notification_event', topic: 'conversation.tag.created', data: {} } as unknown as IntercomWebhookPayload
    const config: ConnectorConfig = { intercomWebhookSecret: 's', zendeskApiToken: 't', zendeskSubdomain: 'd', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.item')
  })

  it('throws when conversation id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '', url: 'https://example.com' } }
    }
    const config: ConnectorConfig = { intercomWebhookSecret: 's', zendeskApiToken: 't', zendeskSubdomain: 'd', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.item.id')
  })

  it('throws when conversation url is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '123', url: '' } }
    }
    const config: ConnectorConfig = { intercomWebhookSecret: 's', zendeskApiToken: 't', zendeskSubdomain: 'd', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.item.url')
  })

  it('throws on non-2xx Zendesk response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '123', url: 'https://example.com' } }
    }
    const config: ConnectorConfig = { intercomWebhookSecret: 's', zendeskApiToken: 't', zendeskSubdomain: 'd', fetch }
    await expect(handle(payload, config)).rejects.toThrow('Zendesk API error: 401 Unauthorized from https://d.zendesk.com/api/v2/tickets.json')
    expect(calls.length).toBe(1)
  })
